class Solution:
    def second_largest(self, xs):
        if len(set(xs)) < 2:
            return None
        max1, max2 = float('-inf'), float('-inf')
        for x in xs:
            if x > max1:
                max2 = max1
                max1 = x
            elif x > max2 and x != max1:
                max2 = x
        return max2

    def third_largest(self, xs):
        n = len(xs)
        count = 0
        for x in xs:
            if x == xs[0]:
                count += 1
        if n == 1 and count < 2:
            return None
        elif n == 1 and count == 2:
            return xs[0]
        else:
            return None
